td.script:
                    var qrcode = new QRCode(document.getElementById("qrcode"), {
                    width : 140,
                    height : 140,
                    correctLevel : QRCode.CorrectLevel.M
                    });

                    function makeCode (msg) {
                    var elText = document.getElementById("text");

                    qrcode.makeCode(msg);
                    }

                    makeCode(document.getElementById("qrvalue").innerHTML);

